mapper.update:
update batch.workflow_run
set run_status = #{runStatus},
    current_node_code = #{currentNodeCode},
    finished_at = #{finishedAt},
    updated_at = current_timestamp
where tenant_id = #{tenantId}
  and id = #{id}

    and run_status in
    #{s}


    and (
        run_status = #{runStatus}
        or run_status not in ('SUCCESS','FAILED','TERMINATED','SUCCESS_DRY_RUN','FAILED_DRY_RUN')
    )

mapper.select:
select *
from batch.workflow_run
where run_status = 'RUNNING'
  and updated_at < #{stuckBefore}
order by updated_at asc, id asc
limit #{limit}

select id
from batch.workflow_run
where run_status in (
    'SUCCESS', 'FAILED', 'TERMINATED', 'SUCCESS_DRY_RUN', 'FAILED_DRY_RUN'
)
  and finished_at is not null
  and finished_at < #{cutoff}
order by id asc
limit #{limit}

